                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
                points, MembershipLevels.levelOf(owner, asOf), MembershipNumbers.of(owner));
        AUDIT.info(OwnerCreatedEvent.of(sequence.next(), owner, asOf).toJson());
    }
}

